        if root_node is None:
            raise Exception(f"Root node not found for value: {root_id}")
        self.__root_node = root_node

        for rule_ref in rule_refs:
            rule_ref.nodes = list(self.__get_root_node(rule_ref.value).values())

    def __get_root_node(self, value: int) -> RootNode:
        root_node = self.__roots.get(value)
        if root_node is None:
            raise Exception(f"Root node not found for value: {value}")
        return root_node

    def __get_initial_pointers(self) -> Pointers:
        pointers = Pointers()

        root_node = self.__root_node
        if root_node is None:
            raise Exception("Root node is not defined")

        for node, parent in self.__fetch_nodes_for_root_node(root_node):
            pointer = GraphPointer(node, parent)
            for resolved_pointer in self.__resolve_pointer(pointer):
                pointers.add(resolved_pointer)
        return pointers

