        nodes = [list(root_node.values()) for root_node in self.__roots.values()]
        graph_view: List[str] = []
        for root_node in nodes:
            for node in root_node:
                graph_view.append(
                    node.print(
                        PrintOpts(
                            pointers=pointers if pointers is not None else Pointers(),
                            show_position=True,
                            colorize=colorize if colors else no_color,
                        )
                    )
                )

