    def __iterate_over_pointers(
        self,
        pointers: Pointers,
    ) -> Iterator[Tuple[UnresolvedRule, List[GraphPointer]]]:
        # keyed by the identity of the rule; identical rules share a single instance,
        # so this groups every pointer sitting on the same rule.
        seen_rules: Dict[int, Tuple[UnresolvedRule, List[GraphPointer]]] = {}
